export const inlineScript = "\n  function selectPlatform(selectedEl) {\n    const cards = document.querySelectorAll('.platform-card');\n    cards.forEach(card => {\n      card.classList.remove('bg-surface-container', 'shadow-md', 'shadow-primary/5', 'selected-active');\n      card.classList.add('bg-surface-container-low', 'shadow-sm');\n\n      const badge = card.querySelector('.w-8');\n      if (badge) {\n        badge.classList.remove('bg-primary', 'text-on-primary', 'font-bold');\n        badge.classList.add('bg-surface-container-high', 'text-on-surface');\n      }\n\n      const check = card.querySelector('.selection-check');\n      if (check) {\n        check.classList.remove('opacity-100');\n        check.classList.add('opacity-0');\n        check.style.fontVariationSettings = \"'FILL' 0\";\n      }\n\n      const text = card.querySelector('.font-headline-sm:not(.w-8)');\n      if (text) {\n        text.classList.remove('font-semibold');\n      }\n    });\n\n    selectedEl.classList.remove('bg-surface-container-low', 'shadow-sm');\n    selectedEl.classList.add('bg-surface-container', 'shadow-md', 'shadow-primary/5', 'selected-active');\n\n    const activeBadge = selectedEl.querySelector('.w-8');\n    if (activeBadge) {\n      activeBadge.classList.remove('bg-surface-container-high', 'text-on-surface');\n      activeBadge.classList.add('bg-primary', 'text-on-primary', 'font-bold');\n    }\n\n    const activeCheck = selectedEl.querySelector('.selection-check');\n    if (activeCheck) {\n      activeCheck.classList.remove('opacity-0', 'group-hover:opacity-40');\n      activeCheck.classList.add('opacity-100');\n      activeCheck.style.fontVariationSettings = \"'FILL' 1\";\n    }\n\n    const activeText = selectedEl.querySelector('.font-headline-sm:not(.w-8)');\n    if (activeText) {\n      activeText.classList.add('font-semibold');\n    }\n  }\n\n  // Reactive League Name Preview\n  const leagueInput = document.getElementById('league-name-input');\n  const previewLabel = document.getElementById('preview-league-label');\n  if (leagueInput && previewLabel) {\n    leagueInput.addEventListener('input', (e) => {\n      previewLabel.textContent = e.target.value.trim() || 'Untitled League';\n    });\n  }\n\n\ndocument.getElementById('review-uncertain-btn')?.addEventListener('click', function handler() {\n  const row = document.getElementById('uncertain-kicker-row');\n  if (!row) return;\n  row.scrollIntoView({ behavior: 'smooth', block: 'center' });\n  row.classList.add('ring-2', 'ring-secondary', 'rounded');\n  this.innerHTML = '<span class=\"material-symbols-outlined text-[18px] text-primary\">check_circle</span><span>KICKER CONFIRMED (LOOKS RIGHT)</span>';\n  this.classList.add('text-primary', 'border-primary/30');\n  this.classList.remove('text-secondary', 'border-secondary/30');\n  this.removeEventListener('click', handler);\n  setTimeout(() => row.classList.remove('ring-2', 'ring-secondary'), 2000);\n});";
